// 🔑 KONFIGURASI MAYAR
const MAYAR_API_TOKEN = 'GANTI_TOKEN_DI_VPS';

// 🏷️ PRODUCT ID per TIER (produk membership Mayar)
const TIERS = {
  yearly: {
    productId: 'd8927ccd-4323-4500-b4f3-2f0e4f82acd1',
    amount: 599000,
    label: 'Langganan 1 Tahun'
  },
  lifetime: {
    productId: '56284414-f48b-47b9-af79-74d2b0f4b2dd',
    amount: 999000,
    label: 'Langganan Life-Time'
  }
};

// 🗄️ SUPABASE (service_role — cuma di server)
const SUPABASE_URL = 'https://qxzvmnbhplgmspdxdbmg.supabase.co';
const SUPABASE_KEY = 'GANTI_SVC_KEY_DI_VPS';

// URL callback & return
const CALLBACK_URL = 'https://n8n.43-133-131-126.sslip.io/webhook/mayar-callback';

// Endpoint Mayar (terverifikasi)
const MAYAR_ENDPOINT = 'https://api.mayar.id/hl/v1/payment/create';

// ============================================================
// HELPER: fetch ke Supabase
// ============================================================
async function supabaseFetch(path, options) {
  const resp = await this.helpers.httpRequest({
    method: options.method || 'GET',
    url: SUPABASE_URL + path,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': 'Bearer ' + SUPABASE_KEY,
      'Content-Type': 'application/json'
    },
    body: options.body ? JSON.stringify(options.body) : undefined,
    json: true,
    timeout: 10000
  });
  return resp;
}

// ============================================================
// VALIDASI VOUCHER di server (anti-hack — jangan percaya harga dari browser)
// ============================================================
async function validateVoucher(code, tier, baseAmount) {
  if (!code) return { valid: false, diskon: 0, voucher_code: '' };

  // 1. Cari voucher di Supabase
  const rows = await supabaseFetch(
    '/rest/v1/vouchers?select=*&code=eq.' + encodeURIComponent(code) + '&active=eq.true',
    { method: 'GET' }
  );
  const v = (Array.isArray(rows) && rows.length > 0) ? rows[0] : null;
  if (!v) return { valid: false, reason: 'Kode voucher tidak ditemukan atau tidak aktif', diskon: 0, voucher_code: code };

  // 3. Cek expired
  if (v.expires_at) {
    const exp = new Date(v.expires_at);
    if (exp < new Date()) {
      return { valid: false, reason: 'Kode voucher sudah kedaluwarsa', diskon: 0, voucher_code: code };
    }
  }

  // 4. Cek kuota
  const maxUses = v.max_uses;
  if (maxUses !== null && maxUses !== undefined && Number(v.used_count || 0) >= Number(maxUses)) {
    return { valid: false, reason: 'Kode voucher sudah habis dipakai', diskon: 0, voucher_code: code };
  }

  // 5. Hitung diskon
  let diskon = 0;
  if (v.type === 'percent') {
    diskon = Math.round(baseAmount * Number(v.value) / 100);
  } else {
    diskon = Math.min(Number(v.value) || 0, baseAmount);
  }

  return { valid: true, diskon: diskon, voucher_code: code, voucher_id: v.id };
}

// ============================================================
// CATAT PEMAKAIAN VOUCHER (used_count + 1)
// ============================================================
async function recordVoucherUse(voucherId) {
  if (!voucherId) return;
  try {
    // Read current used_count
    const rows = await supabaseFetch(
      '/rest/v1/vouchers?select=used_count&id=eq.' + voucherId,
      { method: 'GET' }
    );
    const current = (Array.isArray(rows) && rows.length > 0) ? Number(rows[0].used_count || 0) : 0;
    // Increment
    await supabaseFetch(
      '/rest/v1/vouchers?id=eq.' + voucherId,
      { method: 'PATCH', body: { used_count: current + 1 } }
    );
  } catch (err) {
    console.log('voucher use record warn: ' + err.message);
  }
}

// ============================================================
// MAIN
// ============================================================
const raw = $input.first().json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const nama = (body.nama || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const wa = (body.wa || '').toString().trim();
const discord = (body.discord || '').toString().trim();
const tierInput = (body.tier || 'yearly').toString().trim().toLowerCase();

// Validasi minimal
if (!nama || !email || !wa) {
  throw new Error('Data tidak lengkap: nama, email, dan WA wajib diisi');
}

// Pilih tier
const tier = TIERS[tierInput] ? tierInput : 'yearly';
const t = TIERS[tier];

// Nomor HP Mayar (08... min 10 digit)
const mobile = wa.replace(/[^0-9]/g, '');
if (mobile.length < 10) {
  throw new Error('Nomor WA tidak valid (minimal 10 digit)');
}

// ============ VALIDASI VOUCHER (server-side) ============
const voucherCode = (body.voucher_code || '').toString().trim().toUpperCase();
const voucherCheck = await validateVoucher(voucherCode, tier, t.amount);

// Harga final: base - diskon (diskon dihitung SERVER, bukan dari browser)
let finalAmount = t.amount - voucherCheck.diskon;
// Guard: Mayar min amount 500 — kalau diskon bikin <= 0, set ke 1000
if (finalAmount < 1000) finalAmount = 1000;

// URL return — bawa tier, harga final, & voucher (buat Pixel + tracking)
const RETURN_URL = 'https://xindelabs-workshop.vercel.app/success.html?tier=' + tier + '&harga=' + finalAmount +
  (voucherCheck.valid ? '&voucher=' + voucherCode : '');

// Payload ke Mayar (amount = harga SETELAH diskon)
const payload = {
  name: nama,
  email: email,
  mobile: mobile,
  productId: t.productId,
  amount: finalAmount,
  callbackUrl: CALLBACK_URL,
  returnUrl: RETURN_URL,
  notes: (t.label + ' ' + (discord || '-')).slice(0, 24)
};

// Catat pemakaian voucher (used_count + 1) — fire and forget
if (voucherCheck.valid && voucherCheck.voucher_id) {
  await recordVoucherUse(voucherCheck.voucher_id);
}

return {
  json: {
    endpoint: MAYAR_ENDPOINT,
    authHeader: 'Bearer ' + MAYAR_API_TOKEN,
    payload: payload,
    tier: tier,
    tierLabel: t.label,
    amount: finalAmount,
    amountBase: t.amount,
    diskon: voucherCheck.diskon,
    voucher: voucherCheck.valid ? voucherCode : '',
    voucherValid: voucherCheck.valid,
    voucherReason: voucherCheck.reason || '',
    customer: { nama: nama, email: email, wa: wa, discord: discord }
  }
};

// Response dari Mayar — struktur: { statusCode, messages, data }
const mayarResp = $input.first().json;

// Cek error
if (mayarResp.statusCode && mayarResp.statusCode >= 400) {
  throw new Error('Mayar error: ' + JSON.stringify(mayarResp));
}

const data = mayarResp.data || {};

// Mayar checkout response — field payment URL bisa bervariasi.
// Cek di response asli lo, lalu samakan field-nya di bawah.
// Response Mayar /payment/create: data.link = invoice URL
const paymentUrl = data.link || data.payment_url || data.url || data.checkout_url || data.redirect_url || '';

if (!paymentUrl) {
  // Kalau response belum punya URL (misal butuh step tambahan),
  // log semua data biar kelihatan strukturnya:
  throw new Error('payment_url tidak ditemukan. Response Mayar: ' + JSON.stringify(mayarResp));
}

return {
  json: {
    payment_url: paymentUrl,
    reference: data.reference || data.id || data.payment_ref || '',
    amount: data.amount || 299000
  }
};

// 🗄️ Siapkan data leads (disimpan SEBELUM user bayar — untuk follow-up)
const payment = $input.first().json;
const customer = payment.customer || {};

// cek duplikat sederhana: kalau leads udah ada, jangan dobel
return {
  json: {
    name: customer.nama || payment.nama || '',
    email: customer.email || payment.email || '',
    whatsapp: customer.wa || payment.wa || '',
    discord_id: customer.discord || payment.discord || '',
    status: 'belum',
    source: 'checkout',
    apps_script_endpoint: 'https://script.google.com/macros/s/AKfycbwMmCBIuMsi42s26xEhZr6_57nDLjlxFxym08v3301fnIM3cktrJXADA8WSuzu_wrsT/exec',
    apps_script_payload: {
      action: 'lead',
      nama: customer.nama || payment.nama || '',
      email: customer.email || payment.email || '',
      wa: customer.wa || payment.wa || '',
      discord: customer.discord || payment.discord || '',
      harga: payment.amount || 0
    },
    notes: 'invoice: ' + (payment.reference || '') + ' · tier: ' + (payment.tierLabel || ''),
    supabase_url: 'https://qxzvmnbhplgmspdxdbmg.supabase.co',
    supabase_key: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InF4enZtbmJocGxnbXNwZHhkYm1nIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4NjYwNDIyOSwiZXhwIjoyMTAyMTgwMjI5fQ.UBxJl-T16_ggpFoteFf05hfzENpbgf1rB71sawQhl1M'
  }
};
